use serde_json::json;
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs,io::Read,path::Path,process::{Command,Stdio}};
use std::os::unix::fs::FileTypeExt;
fn hash(p:&Path)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn copy(src:&Path,dst:&Path,root:&Path,index:&mut BTreeMap<String,String>){assert!(src.symlink_metadata().unwrap().file_type().is_file());fs::create_dir_all(dst.parent().unwrap()).unwrap();let digest=if src.file_name().is_some_and(|n|n=="perf.data"){let before=fs::metadata(src).unwrap();let out=Command::new("sudo").args(["-n","sha256sum"]).arg(src).output().unwrap();assert!(out.status.success());let digest=String::from_utf8(out.stdout).unwrap().split_whitespace().next().unwrap().to_owned();let file=fs::File::create(dst).unwrap();assert!(Command::new("sudo").args(["-n","cat"]).arg(src).stdout(Stdio::from(file)).status().unwrap().success());let after=fs::metadata(src).unwrap();assert_eq!(before.len(),after.len());assert_eq!(before.modified().unwrap(),after.modified().unwrap());digest}else{fs::copy(src,dst).unwrap();hash(src)};assert_eq!(hash(dst),digest);assert!(index.insert(dst.strip_prefix(root).unwrap().to_str().unwrap().into(),digest).is_none());}
fn tree(src:&Path,dst:&Path,root:&Path,index:&mut BTreeMap<String,String>){let mut entries=fs::read_dir(src).unwrap().map(|e|e.unwrap().path()).collect::<Vec<_>>();entries.sort();for p in entries{let name=p.file_name().unwrap();if name=="target"{continue}let q=dst.join(name);let kind=p.symlink_metadata().unwrap().file_type();if kind.is_dir(){tree(&p,&q,root,index)}else if kind.is_fifo(){assert!(["ctl","ack"].iter().any(|n|name==*n));}else if name!="candidate-sdk"{copy(&p,&q,root,index)}}}
fn main(){let src=Path::new("/tmp/zopro-outlined-snapshot-fence");let report=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-outlined-snapshot-fence");let dst=report.join("artifacts");assert!(!dst.exists());let mut index=BTreeMap::new();for name in ["experiment.json","accepted-manifest.json","prepare.rs","prepare.json","parent-source-pins.json","outline-audit.json","native-plan.json","build-input-pins.json","native.log","source-audit.rs","source-audit.json","ordering-review.md","upstream-deque.rs","upstream-registry.rs","upstream-pins.json","lock-audit.json","protocol.rs","protocol-initial.rs","protocol-compile-failure.log","protocol.log","linked-scheduler-libraries.json","all-nine-template.json","perf-template.json","perf-plan.json","input-pins.json","preflight-plan.json","inventory-preflight.sh","validate-preflight.jq","preflight-validation.json","preflight-proof-inventory.json","preflight.log","perf.log","analyze.rs","analyze-tests.log","pilot-result.json","make-closeout.rs","closeout.rs","closeout.json","proof-inventory.json","codegen-gate.rs","codegen-gate.json","codegen.txt","source.patch","publication-repair.json","write-report.rs","next-design.md","work-state.json","publish.rs"]{copy(&src.join(name),&dst.join(name),&dst,&mut index)}for name in ["candidate","model","native","preflight","preflight-proofs","perf"]{tree(&src.join(name),&dst.join(name),&dst,&mut index)}let raw=index.keys().filter(|p|p.ends_with("/perf.data")).count();let symbols=index.keys().filter(|p|p.ends_with("/symbols/stdout.log")).count();assert_eq!(raw,12);assert_eq!(symbols,12);let member=|p:&&String|p.ends_with(".proof")||p.ends_with(".public");let members=index.keys().filter(|p|(p.starts_with("perf/")||p.starts_with("preflight-proofs/"))&&member(p)).count();let fixtures=index.keys().filter(|p|p.starts_with("candidate/")&&member(p)).count();assert_eq!(members,620);assert_eq!(fixtures,2);fs::write(dst.join("SHA256SUMS"),index.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>()).unwrap();fs::write(dst.join("artifact-index.json"),format!("{}\n",serde_json::to_string_pretty(&json!({"files":index.len(),"proof_public_members":members,"additional_source_fixture_members":fixtures,"raw_perf":raw,"expanded_symbols":symbols,"sha256":index,"scope":"Archived frozen source/codegen/protocol/test/measurement/proof copies.12raw captures and12expanded streams retained locally, ignored Git. Executables/compiler caches represented by exact build/link hashes. Previous inlined source/executable identified by parent pins and prior report; no additional duplicate old source fixtures counted."})).unwrap())).unwrap();fs::write(report.join(".gitignore"),"/artifacts/**/perf.data\n/artifacts/**/symbols/stdout.log\n").unwrap();fs::write(report.join(".gitattributes"),"# Preserve exact archived source/output bytes.\nartifacts/** -whitespace\n").unwrap();println!("ARCHIVE_VERIFIED {}files620newproof/public2sourcefixtures12raw12expanded",index.len());}
